"""Transactional SQLite v4 schema for independent validation and delivery."""


VALIDATION_SCHEMA = (
    "CREATE TABLE validation_operations(operation_id TEXT PRIMARY KEY, request_digest TEXT NOT NULL, operation_kind TEXT NOT NULL CHECK(operation_kind IN ('validate','build','deliver')), status TEXT NOT NULL CHECK(status IN ('prepared','running','passed','failed','inconclusive','cancelled','succeeded','unknown')), owner_token TEXT NOT NULL DEFAULT '', request_snapshot TEXT NOT NULL, result_snapshot TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
    "CREATE TABLE validation_id_registry(project_id TEXT NOT NULL, object_type TEXT NOT NULL CHECK(object_type IN ('command','gate')), stable_id TEXT NOT NULL, first_seen_revision INTEGER NOT NULL, last_seen_revision INTEGER NOT NULL, definition_digest TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(project_id,object_type,stable_id), FOREIGN KEY(project_id) REFERENCES projects(project_id))",
    "CREATE TABLE validation_runs(validation_run_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, request_digest TEXT NOT NULL, project_id TEXT NOT NULL, task_id TEXT NOT NULL, definition_revision INTEGER NOT NULL, definition_digest TEXT NOT NULL, attempt_id TEXT, checkpoint_operation_id TEXT NOT NULL, workspace_id TEXT NOT NULL, commit_oid TEXT NOT NULL, tree_oid TEXT NOT NULL, configuration_snapshot TEXT NOT NULL, configuration_digest TEXT NOT NULL, policy_snapshot TEXT NOT NULL, policy_digest TEXT NOT NULL, runtime_profile TEXT NOT NULL CHECK(runtime_profile IN ('local-explicit','docker-isolated')), status TEXT NOT NULL CHECK(status IN ('requested','preflight','running','passed','failed','inconclusive','cancelled')), unresolved INTEGER NOT NULL DEFAULT 0 CHECK(unresolved IN (0,1)), requested_by TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, FOREIGN KEY(operation_id) REFERENCES validation_operations(operation_id), FOREIGN KEY(project_id,task_id,definition_revision) REFERENCES task_definitions(project_id,task_id,definition_revision), FOREIGN KEY(workspace_id,project_id,task_id,definition_revision) REFERENCES workspaces(workspace_id,project_id,task_id,definition_revision), FOREIGN KEY(checkpoint_operation_id) REFERENCES git_checkpoints(operation_id), FOREIGN KEY(attempt_id) REFERENCES execution_attempts(attempt_id))",
    "CREATE UNIQUE INDEX one_active_validation_per_project ON validation_runs(project_id) WHERE status IN ('requested','preflight','running') OR unresolved=1",
    "CREATE INDEX validation_runs_by_task ON validation_runs(project_id,task_id,definition_revision,created_at)",
    "CREATE TABLE validation_gate_results(gate_result_id TEXT PRIMARY KEY, validation_run_id TEXT NOT NULL, gate_id TEXT NOT NULL, gate_version INTEGER NOT NULL, gate_definition_digest TEXT NOT NULL, criterion_ids_json TEXT NOT NULL, required INTEGER NOT NULL CHECK(required IN (0,1)), validator_id TEXT NOT NULL, validator_version TEXT NOT NULL, validator_digest TEXT NOT NULL, snapshot_digest TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','preflight','running','passed','failed','inconclusive','cancelled','not_run')), exit_code INTEGER, reason TEXT NOT NULL DEFAULT '', capabilities_json TEXT NOT NULL, process_identity TEXT NOT NULL DEFAULT '', stdout_digest TEXT NOT NULL DEFAULT '', stderr_digest TEXT NOT NULL DEFAULT '', stdout_bytes INTEGER NOT NULL DEFAULT 0, stderr_bytes INTEGER NOT NULL DEFAULT 0, logs_retained INTEGER NOT NULL DEFAULT 1 CHECK(logs_retained IN (0,1)), truncated INTEGER NOT NULL DEFAULT 0 CHECK(truncated IN (0,1)), started_at TEXT, finished_at TEXT, UNIQUE(validation_run_id,gate_id), FOREIGN KEY(validation_run_id) REFERENCES validation_runs(validation_run_id))",
    "CREATE TABLE validation_snapshots(snapshot_id TEXT PRIMARY KEY, validation_run_id TEXT NOT NULL UNIQUE, source_commit_oid TEXT NOT NULL, source_tree_oid TEXT NOT NULL, snapshot_digest TEXT NOT NULL, manifest_json TEXT NOT NULL, storage_path TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 0 AND 2147483648), state TEXT NOT NULL CHECK(state IN ('prepared','materialized','verified','quarantined','expired','failed')), created_at TEXT NOT NULL, expires_at TEXT, FOREIGN KEY(validation_run_id) REFERENCES validation_runs(validation_run_id))",
    "CREATE TABLE validation_artifacts(artifact_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, source_run_id TEXT NOT NULL, project_id TEXT NOT NULL, task_id TEXT NOT NULL, definition_revision INTEGER NOT NULL, checkpoint_operation_id TEXT NOT NULL, source_commit_oid TEXT NOT NULL, source_tree_oid TEXT NOT NULL, snapshot_digest TEXT NOT NULL, builder_id TEXT NOT NULL, builder_version TEXT NOT NULL, builder_digest TEXT NOT NULL, configuration_digest TEXT NOT NULL, dependency_digest TEXT NOT NULL, artifact_digest TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 0 AND 268435456), storage_path TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('verified','expired','corrupt')), pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN (0,1)), created_at TEXT NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY(operation_id) REFERENCES validation_operations(operation_id), FOREIGN KEY(source_run_id) REFERENCES validation_runs(validation_run_id), FOREIGN KEY(project_id,task_id,definition_revision) REFERENCES task_definitions(project_id,task_id,definition_revision), FOREIGN KEY(checkpoint_operation_id) REFERENCES git_operations(operation_id))",
    "CREATE TABLE validation_deliveries(operation_id TEXT PRIMARY KEY, request_digest TEXT NOT NULL, artifact_id TEXT NOT NULL, destination_id TEXT NOT NULL, authorization_id TEXT NOT NULL, authorized_by TEXT NOT NULL, authorized_at TEXT NOT NULL, provider_id TEXT NOT NULL DEFAULT '', provider_version TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('prepared','running','succeeded','failed','unknown')), credential_reference_ids_json TEXT NOT NULL DEFAULT '[]', receipt_digest TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(operation_id) REFERENCES validation_operations(operation_id), FOREIGN KEY(artifact_id) REFERENCES validation_artifacts(artifact_id))",
    "CREATE TABLE validation_delivery_authorizations(authorization_id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, project_id TEXT NOT NULL, artifact_id TEXT NOT NULL, destination_id TEXT NOT NULL, artifact_digest TEXT NOT NULL, authorized_by TEXT NOT NULL, authorized_at TEXT NOT NULL, UNIQUE(operation_id,destination_id,artifact_digest), FOREIGN KEY(project_id) REFERENCES projects(project_id), FOREIGN KEY(artifact_id) REFERENCES validation_artifacts(artifact_id))",
    "CREATE TABLE validation_events(event_id INTEGER PRIMARY KEY AUTOINCREMENT, operation_id TEXT NOT NULL, validation_run_id TEXT, kind TEXT NOT NULL, payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=4096), occurred_at TEXT NOT NULL, FOREIGN KEY(operation_id) REFERENCES validation_operations(operation_id), FOREIGN KEY(validation_run_id) REFERENCES validation_runs(validation_run_id))",
    "CREATE TRIGGER validation_evidence_operation_guard BEFORE INSERT ON evidence WHEN EXISTS(SELECT 1 FROM operations WHERE operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM execution_attempts WHERE operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM git_operations WHERE operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM validation_operations WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'evidence operation_id already used'); END",
    "CREATE TRIGGER validation_verified_evidence_no_update BEFORE UPDATE ON evidence WHEN OLD.kind='verified' BEGIN SELECT RAISE(ABORT,'verified evidence is append-only'); END",
    "CREATE TRIGGER validation_verified_evidence_no_delete BEFORE DELETE ON evidence WHEN OLD.kind='verified' BEGIN SELECT RAISE(ABORT,'verified evidence is append-only'); END",
    "CREATE TRIGGER f2_operation_evidence_guard BEFORE INSERT ON operations WHEN EXISTS(SELECT 1 FROM evidence WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by evidence'); END",
    "CREATE TRIGGER f3_operation_evidence_guard BEFORE INSERT ON execution_attempts WHEN EXISTS(SELECT 1 FROM evidence WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by evidence'); END",
    "CREATE TRIGGER f4_operation_evidence_guard BEFORE INSERT ON git_operations WHEN EXISTS(SELECT 1 FROM evidence WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by evidence'); END",
    "CREATE INDEX validation_gate_results_by_run ON validation_gate_results(validation_run_id,gate_id)",
    "CREATE INDEX validation_snapshots_by_expiry ON validation_snapshots(state,expires_at)",
    "CREATE INDEX validation_artifacts_by_expiry ON validation_artifacts(status,pinned,expires_at)",
    "CREATE INDEX validation_deliveries_by_artifact ON validation_deliveries(artifact_id,status)",
    "CREATE INDEX validation_events_by_operation ON validation_events(operation_id,event_id)",
    "CREATE TRIGGER validation_events_no_update BEFORE UPDATE ON validation_events BEGIN SELECT RAISE(ABORT,'validation events are append-only'); END",
    "CREATE TRIGGER validation_events_no_delete BEFORE DELETE ON validation_events BEGIN SELECT RAISE(ABORT,'validation events are append-only'); END",
    "CREATE TRIGGER validation_delivery_authorization_no_update BEFORE UPDATE ON validation_delivery_authorizations BEGIN SELECT RAISE(ABORT,'delivery authorization is immutable'); END",
    "CREATE TRIGGER validation_delivery_authorization_no_delete BEFORE DELETE ON validation_delivery_authorizations BEGIN SELECT RAISE(ABORT,'delivery authorization is immutable'); END",
    "CREATE TRIGGER validation_operation_global_guard BEFORE INSERT ON validation_operations WHEN EXISTS(SELECT 1 FROM operations WHERE operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM execution_attempts WHERE operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM git_operations WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used in another domain'); END",
    "CREATE TRIGGER f2_operation_validation_guard BEFORE INSERT ON operations WHEN EXISTS(SELECT 1 FROM validation_operations WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by validation'); END",
    "CREATE TRIGGER f3_operation_validation_guard BEFORE INSERT ON execution_attempts WHEN EXISTS(SELECT 1 FROM validation_operations WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by validation'); END",
    "CREATE TRIGGER f4_operation_validation_guard BEFORE INSERT ON git_operations WHEN EXISTS(SELECT 1 FROM validation_operations WHERE operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation_id already used by validation'); END",
    "CREATE TRIGGER validation_run_snapshot_immutable BEFORE UPDATE OF request_digest,project_id,task_id,definition_revision,definition_digest,attempt_id,checkpoint_operation_id,workspace_id,commit_oid,tree_oid,configuration_snapshot,configuration_digest,policy_snapshot,policy_digest,runtime_profile,requested_by ON validation_runs BEGIN SELECT RAISE(ABORT,'validation run provenance is immutable'); END",
    "CREATE TRIGGER validation_run_no_delete BEFORE DELETE ON validation_runs BEGIN SELECT RAISE(ABORT,'validation runs are immutable audit records'); END",
    "CREATE TRIGGER validation_run_status_transition BEFORE UPDATE OF status ON validation_runs WHEN NOT ((OLD.status='requested' AND NEW.status IN ('preflight','failed','inconclusive','cancelled')) OR (OLD.status='preflight' AND NEW.status IN ('running','failed','inconclusive','cancelled')) OR (OLD.status='running' AND NEW.status IN ('passed','failed','inconclusive','cancelled')) OR OLD.status=NEW.status) BEGIN SELECT RAISE(ABORT,'invalid validation run state transition'); END",
    "CREATE TRIGGER validation_gate_result_provenance_immutable BEFORE UPDATE OF validation_run_id,gate_id,gate_version,gate_definition_digest,criterion_ids_json,required,validator_id,validator_version,validator_digest,snapshot_digest ON validation_gate_results BEGIN SELECT RAISE(ABORT,'gate result provenance is immutable'); END",
    "CREATE TRIGGER validation_gate_result_terminal_immutable BEFORE UPDATE ON validation_gate_results WHEN OLD.status IN ('passed','failed','inconclusive','cancelled','not_run') AND NOT (OLD.logs_retained=1 AND NEW.logs_retained=0 AND OLD.gate_result_id=NEW.gate_result_id AND OLD.validation_run_id=NEW.validation_run_id AND OLD.gate_id=NEW.gate_id AND OLD.gate_version=NEW.gate_version AND OLD.gate_definition_digest=NEW.gate_definition_digest AND OLD.criterion_ids_json=NEW.criterion_ids_json AND OLD.required=NEW.required AND OLD.validator_id=NEW.validator_id AND OLD.validator_version=NEW.validator_version AND OLD.validator_digest=NEW.validator_digest AND OLD.snapshot_digest=NEW.snapshot_digest AND OLD.status=NEW.status AND OLD.exit_code IS NEW.exit_code AND OLD.reason=NEW.reason AND OLD.capabilities_json=NEW.capabilities_json AND OLD.process_identity=NEW.process_identity AND OLD.stdout_digest=NEW.stdout_digest AND OLD.stderr_digest=NEW.stderr_digest AND OLD.stdout_bytes=NEW.stdout_bytes AND OLD.stderr_bytes=NEW.stderr_bytes AND OLD.truncated=NEW.truncated AND OLD.started_at IS NEW.started_at AND OLD.finished_at IS NEW.finished_at) BEGIN SELECT RAISE(ABORT,'terminal gate result immutable except log-retention marker'); END",
    "CREATE TRIGGER validation_gate_status_transition BEFORE UPDATE OF status ON validation_gate_results WHEN NOT ((OLD.status='queued' AND NEW.status IN ('preflight','not_run')) OR (OLD.status='preflight' AND NEW.status IN ('running','failed','inconclusive','cancelled','not_run')) OR (OLD.status='running' AND NEW.status IN ('passed','failed','inconclusive','cancelled'))) BEGIN SELECT RAISE(ABORT,'invalid gate state transition'); END",
    "CREATE TRIGGER validation_gate_result_no_delete BEFORE DELETE ON validation_gate_results BEGIN SELECT RAISE(ABORT,'gate results are immutable'); END",
    "CREATE TRIGGER validation_snapshot_identity_immutable BEFORE UPDATE OF validation_run_id,source_commit_oid,source_tree_oid,snapshot_digest,manifest_json,storage_path,size_bytes ON validation_snapshots BEGIN SELECT RAISE(ABORT,'snapshot identity is immutable'); END",
    "CREATE TRIGGER validation_snapshot_no_delete BEFORE DELETE ON validation_snapshots BEGIN SELECT RAISE(ABORT,'snapshot records are immutable'); END",
)
